def set_state(self, state, grad_enabled=False):
    self.t = 0

    self.simulator.cur_substep_global = 0
    self.simulator.set_state(0, state)

    if grad_enabled:
        self.enable_grad()
    else:
        self.disable_grad()

    if self.loss:
        self.loss.reset()

